# Fixed transform - don't overwrite preserved positions
def apply_transform(grid, gen=6, preserved_input_values=[0, 9]):
    h = len(grid)
    w = len(grid[0])

    # Create a mask of preserved positions from input (values 0 and 9)
    preserved_mask = [[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in preserved_input_values:
                preserved_mask[r][c] = True

    # Start with copy of input
    output = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Process generators - only write to non-preserved positions
    for r in range(h):
        for c in range(w):
            if grid[r][c] == gen:
                # Position itself becomes 0 (overwrite)
                output[r][c] = 0
                # Above becomes 0
                if r > 0:
                    if not preserved_mask[r-1][c]:
                        output[r-1][c] = 0
                # Below becomes 9
                if r < h - 1:
                    if not preserved_mask[r+1][c]:
                        output[r+1][c] = 9

    return output

